-- Full Mx partner contract template (v3) — enrolment form + partnership plan appendix.
-- Replaces v2 appendix-only content. Run after 0380.

UPDATE public.merchant_agreement_templates
SET is_active = false, effective_to = now(), updated_at = now()
WHERE template_key = 'DEFAULT_CHILD_ONBOARDING_AGREEMENT'
  AND version = 'v2'
  AND is_active = true;

INSERT INTO public.merchant_agreement_templates (
  template_key,
  title,
  version,
  content_markdown,
  pdf_url,
  applies_to,
  is_active,
  effective_from
)
VALUES (
  'DEFAULT_CHILD_ONBOARDING_AGREEMENT',
  'Merchant Partner Agreement',
  'v3',
  $mx_contract_v3${"schemaVersion":1,"formTitle":"RESTAURANT PARTNER ENROLMENT FORM (\"FORM\") FOR FOOD ORDERING AND DELIVERY SERVICES","definitions":[{"term":"Platform","meaning":"The food ordering and delivery platform operated by the Company, including its website, mobile applications, and associated services."},{"term":"Restaurant Partner","meaning":"The legal entity (restaurant/outlet) that has agreed to list its menu and fulfil Orders through the Platform, as identified in this Form."},{"term":"Customer","meaning":"An end-user who places an Order for food and/or beverages through the Platform."},{"term":"Order","meaning":"A request placed by a Customer through the Platform for food and/or beverages to be supplied by the Restaurant Partner."},{"term":"Order Value","meaning":"The amount payable by the Customer for an Order (including food, beverages, packaging, and applicable taxes), as received by the Platform."},{"term":"Charges","meaning":"The commission and other fees payable by the Restaurant Partner to the Platform as set out in Annexure A and the Terms."},{"term":"Services","meaning":"The services provided by the Platform to the Restaurant Partner as described in this Form and the Terms."},{"term":"Terms","meaning":"The Terms and Conditions for food ordering and delivery services, as amended from time to time, and which are incorporated by reference into this Form."}],"sections":[{"title":"I. Services","bullets":["Order placement and catalog hosting: The Platform provides the order placement mechanism for Customers to place Orders with the Restaurant Partners on a real-time basis and hosts the menu and price lists as provided by the Restaurant Partners.","Demand generation and marketing: The Platform helps bring new Customers to Restaurant Partners through targeted marketing, discovery, and a seamless food ordering experience.","Logistics: The Platform enables a reliable delivery ecosystem for fulfilling the Restaurant Partner's Orders.","Support: A support team is available to help resolve issues for Customers and Restaurant Partners.","Technology: The Platform builds and supports products including payment and order management infrastructure."]},{"title":"II. Charges","paragraphs":["For the Services above, the Restaurant Partner shall pay the applicable Charges as set out in Annexure A and the Terms. All amounts are subject to applicable taxes (including GST). The Platform shall raise tax invoices as per applicable law."]},{"title":"III. Payment Settlement","paragraphs":["The Platform shall transfer the Order Value received to the Restaurant Partner, after deduction of Charges, on a weekly basis. Settlement shall be made to the bank account details provided in Annexure B. The payment settlement day for Orders serviced from Monday to Sunday shall be on or before Thursday of the following week. If the settlement day falls on a bank holiday, it shall be the next working day."]},{"title":"IV. Additional Terms","bullets":["The Restaurant Partner shall not charge the Customer for anything other than food, beverages, and packaging on the Platform.","The Restaurant Partner will maintain equal or lower prices for products on the Platform as compared to its direct channels.","The Restaurant Partner will not send marketing material with Orders that discourages Customers from ordering via the Platform.","This Form and its annexures, together with the Terms, constitute the entire agreement between the Parties and are legally binding."]},{"title":"Declaration","paragraphs":["I/We have read and understood this Form and the Terms. I/We accept and agree to be bound by the Terms. I/We represent and warrant that I/we are duly authorized to sign this Form on behalf of the Restaurant Partner."]}],"annexureA":{"description":"Commission and charges payable by the Restaurant Partner to the Platform for food ordering and delivery services:","table":{"headers":["Period","Commission (on Order Value)","Remarks"],"rows":[["First month from Go-Live","0%","No commission for the first calendar month from the date the restaurant goes live on the Platform."],["From second month onwards","15% + GST","Fifteen per cent (15%) of the Order Value plus applicable GST. Subject to commercial terms communicated from time to time."]]}},"certification":"I/We hereby certify that the details provided above are correct, that the bank account is an account legally opened and maintained by me/our organization, and that I/we shall be liable to the maximum extent possible under applicable law in the event any details provided above are found to be incorrect.","partnershipPlanTerms":"Terms and Conditions\nPartnership Plan\n\nYou hereby agree and acknowledge that as part of the Plan and in consideration of the agreed onboarding fees, the Platform will provide onboarding services in accordance with the following terms and conditions:\n\n(a) The one-time photoshoot service of up to thirty (30) images of your menu dishes through authorised third-party service providers will be valid for a period of ninety (90) days from the date your restaurant goes live on the Platform for food ordering and delivery services. You will not be able to avail this photoshoot service if the same is not availed within the said ninety (90) days period.\n\n(b) For the photoshoot services, the designated photoshoot personnel will be available at your restaurant location at the date and time as communicated by you for a maximum duration of three (3) hours. It will be your responsibility to ensure all dishes are prepared and ready for the shoot prior to or immediately upon the arrival of the photoshoot personnel for the photoshoot personnel to complete the photoshoot within the stipulated timeframe.\n\n(c) You acknowledge and agree that rescheduling the photoshoot is allowed/permissible only once.\n\n(d) You acknowledge and agree that the one-time ads credit worth up to INR 1,500/- that you receive under the Plan is subject to an eligibility criteria which will be communicated to you by the Platform from time to time. If your restaurant meets this criteria you will be able to claim this discount. The discount must be utilized within thirty (30) days from the date your restaurant goes live under this plan.\n\n(e) The Plan only offers additional benefits for your restaurant page and the Platform does not provide any warranty or guarantee towards the reach, engagement and/or performance for your restaurant.\n\n(f) You agree and acknowledge that in the event your service fee is revised or reduced from the agreed service fee, the Platform reserves the right to void the unclaimed benefits as a part of the Plan.\n\n(g) The offering with respect to partner discounts shall be governed by separate terms and conditions as may be communicated to you from time to time.\n\n(h) You have an option to make an upfront payment of the onboarding fee at time of onboarding or reduction from your weekly payouts for food ordering and delivery services in five (5) equal installments.\n\n1) In case you make an upfront payment of the onboarding fee at the time of onboarding, in the event of a payment failure on the platform, the amount of the onboarding fee will be refunded to your source account within three (3) business days. Additionally, if your restaurant is not successfully onboarded on the Platform within fifteen (15) days from the date of receipt of payment of the onboarding fee, due to reasons not attributable to you, the onboarding fee will be refunded to you.\n\n2) In case you choose a post-paid model of payment of onboarding fee, i.e., by way of reduction from your weekly payouts, the onboarding fee will reflect separately and identifiable in your statement of account.\n\n3) For clarity, the onboarding fee payable for the onboarding services is independent of the fee payable by you to the Platform under the terms and conditions for the food ordering and delivery services.\n\n4) The Platform shall raise tax invoice as per GST laws for such onboarding fee. If as per the applicable tax laws, You are liable to deduct taxes at source (\"TDS\") on the Onboarding Fees payable to the Platform, then You shall deposit the applicable TDS from your own pocket and shall claim a refund of such TDS from the Platform upon submission of TDS certificate within time stipulated under the applicable law.\n\n5) If you already have an existing restaurant on the Platform and are adding a new restaurant, a reduced onboarding fee will be applicable."}$mx_contract_v3$,
  NULL,
  '{}'::jsonb,
  true,
  now()
)
ON CONFLICT (template_key, version) DO UPDATE SET
  title = EXCLUDED.title,
  content_markdown = EXCLUDED.content_markdown,
  is_active = true,
  effective_to = NULL,
  effective_from = now(),
  updated_at = now();

UPDATE public.merchant_agreement_templates
SET is_active = false, effective_to = COALESCE(effective_to, now()), updated_at = now()
WHERE template_key = 'DEFAULT_CHILD_ONBOARDING_AGREEMENT'
  AND version <> 'v3'
  AND is_active = true;
